export function getAsyncSearchIdQueryKey(
  args: MaybeRefOrGetter<InferRequestType<(typeof client._async_search)[':id']['$get']>>,
) {
  return ['_async_search', '/_async_search/:id', toValue(args)] as const
}

export function getAsyncSearchIdQueryOptions(
  args: MaybeRefOrGetter<InferRequestType<(typeof client._async_search)[':id']['$get']>>,
  options?: ClientRequestOptions,
) {
  return {
    queryKey: computed(() => getAsyncSearchIdQueryKey(args)),
    queryFn({ signal }: QueryFunctionContext) {
      return parseResponse(
        client._async_search[':id'].$get(toValue(args), {
          ...options,
          init: { ...options?.init, signal },
        }),
      )
    },
  }
}

export function useAsyncSearchId<
  TData = Awaited<
    ReturnType<
      typeof parseResponse<Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>>
    >
  >,
  TError = DefaultError,
>(
  args: MaybeRefOrGetter<InferRequestType<(typeof client._async_search)[':id']['$get']>>,
  options?: {
    query?: Omit<
      Extract<
        UseQueryOptions<
          Awaited<
            ReturnType<
              typeof parseResponse<
                Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>
              >
            >
          >,
          TError,
          TData,
          Awaited<
            ReturnType<
              typeof parseResponse<
                Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>
              >
            >
          >,
          ReturnType<typeof getAsyncSearchIdQueryKey>
        >,
        { queryKey: unknown }
      >,
      'queryKey' | 'queryFn'
    >
    options?: ClientRequestOptions
  },
  queryClient?: QueryClient,
) {
  const { query: queryOptions, options: clientOptions } = options ?? {}
  return useQuery<
    Awaited<
      ReturnType<
        typeof parseResponse<Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>>
      >
    >,
    TError,
    TData,
    ReturnType<typeof getAsyncSearchIdQueryKey>
  >(
    {
      ...queryOptions,
      queryKey: computed(() => getAsyncSearchIdQueryKey(args)),
      queryFn({ signal }) {
        return parseResponse(
          client._async_search[':id'].$get(toValue(args), {
            ...clientOptions,
            init: { ...clientOptions?.init, signal },
          }),
        )
      },
    },
    queryClient,
  )
}

